#include "field_qq.hpp"
#include <array>
using Mon=array<int,7>;
int main(int argc,char**argv){fmpq_mpoly_ctx_init(ctx,2,ORD_LEX);{vector<Mon>m2,m4;for(int a=0;a<7;a++)for(int b=a;b<7;b++){Mon m{};m[a]++;m[b]++;m2.push_back(m);}for(int a=0;a<7;a++)for(int b=a;b<7;b++)for(int c=b;c<7;c++)for(int d=c;d<7;d++){Mon m{};m[a]++;m[b]++;m[c]++;m[d]++;m4.push_back(m);}map<Mon,int>ix;for(int i=0;i<(int)m4.size();i++)ix[m4[i]]=i;vector<Row>rows;ifstream qin(argv[1]);int nr,nc;qin>>nr>>nc;for(int z=0;z<nr;z++){int nn;qin>>nn;Row q;for(int k=0;k<nn;k++){int j;qin>>j;Rat x;readpoly(qin,x.n);readpoly(qin,x.d);assert(fmpq_mpoly_is_one(x.d,ctx));q.emplace(j,std::move(x));}for(auto&shift:m2){Row row;for(auto&[j,v]:q){Mon m=shift;for(int k=0;k<7;k++)m[k]+=m2[j][k];row.emplace(ix.at(m),v);}rows.push_back(std::move(row));}}
for(int ff=2;ff<=3;ff++){ifstream in(argv[ff]);int n;in>>n;for(int zz=0;zz<n;zz++){int id,nn;in>>id>>nn;map<Mon,Rat>ground;for(int z=0;z<nn;z++){Mon m;for(int&v:m)in>>v;Rat x;readpoly(in,x.n);ground.emplace(m,std::move(x));}if(ground.empty())continue;if(ff==2){for(int a=0;a<7;a++){Row row;for(auto&[m,v]:ground){Mon shifted=m;shifted[a]++;row.emplace(ix.at(shifted),v);}rows.push_back(std::move(row));}}else{Row row;for(auto&[m,v]:ground)row.emplace(ix.at(m),v);rows.push_back(std::move(row));}}}
ofstream out(argv[4]);out<<rows.size()<<" 210\n";for(auto&r:rows){out<<r.size()<<'\n';for(auto&[j,v]:r){out<<j<<'\n';writepoly(out,v.n);writepoly(out,v.d);}}cerr<<"rows "<<rows.size()<<'\n';}fmpq_mpoly_ctx_clear(ctx);flint_cleanup();}
